$ python3 -B - <<'PY'
import os,pathlib,json
root=pathlib.Path(os.environ['NOODLE_PROJECT_DIR'])/'.noodle'/'sessions'/os.environ['NOODLE_SESSION_ID']
print('own_session_directory:',root)
if root.is_dir():
 for p in root.iterdir():
  if p.is_file() and 'event' in p.name:
   for line in p.read_text().splitlines():
    try: e=json.loads(line)
    except json.JSONDecodeError: continue
    if e.get('type')=='stage_message': print('event_readback:',json.dumps(e))
else:
 print('Own session directory not found; emit exit 0 is the available acknowledgement.')
PY

